func FrSetting(code int32) int32 {
	// The named settings (SPEC 9.4, 13): `tl-trusted` (P7.0), `agree-sim` (P7.2) are theirs; the rest are first values (P10.1 calibrates).
	if code == 0 {
		return 0
	}
	if code == 1 {
		return 1
	}
	if code == 2 {
		return tlhealth.ThTrusted()
	}
	if code == 3 {
		return health.HhAgreeSim()
	}
	// `agree-low`: the case-folded similarity under which a healthy text layer and its OCR are in real disagreement
	if code == 4 {
		return 300
	}
	// `ocr-plausible`: the plausibility (1000 minus 8) an OCR word needs to replace or to be admitted
	if code == 5 {
		return 600
	}
	// `ocr-admit`: the mean word score an OCR-only word needs to be admitted to the body
	if code == 6 {
		return 600
	}
	// `scan-region`: the share of the page (per mille) an image placement covers for text in it to be admitted (a scanned insert)
	if code == 7 {
		return 500
	}
	// `ocr-min-len`: the code points an OCR-only group needs to be admitted (a bullet or a rule fragment read as one letter is not text)
	if code == 8 {
		return 2
	}
	// `ocr-admit-conf`: the engine confidence an OCR-only group needs to be admitted
	if code == 9 {
		return 700
	}
	// `ocr-near-max`: an OCR-only group overlapping a text-layer word this much (per mille) is that word's ink read again, not new text
	if code == 10 {
		return 150
	}
	// `agree-min` (P7.2): the page agreement under which OCR-only words are not admitted
	if code == 11 {
		return health.HhAgreeMin()
	}
	// `hid-margin` (P7.6): an OCR word whose engine margin (per mille) is under this is a close call, and a hidden word may stand against it
	if code == 40 {
		return 600
	}
	// `hid-ink` (P7.6): the kin ink (per mille of a hidden word's box) from which there is ink under it
	if code == 41 {
		return 30
	}
	return 0
}

